# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MUTASYON VE MODİFİKASYON KARŞILAŞTIRMASI</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">MUTASYON (Gen Yapısı Değişir)</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• DNA dizilimi veya kromozom sayısı değişir.</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• Radyasyon, X ışını, kimyasallar sebep olur.</text>\n  <text x="55" y="156" font-size="11.5" font-weight="bold" fill="#991b1b">• Üreme hücresindeyse KALITSALDIR;</text>\n  <text x="65" y="174" font-size="11" fill="#475569">vücut hücresindeyse kalıtsal değildir.</text>\n  <text x="55" y="198" font-size="11.5" fill="#334155">• Etken kalksa da eski haline dönmez.</text>\n  <text x="55" y="220" font-size="11" font-weight="bold" fill="#b91c1c">Örnek: Down sendromu, Albinoluk, Van kedisi</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">MODİFİKASYON (Gen İşleyişi Değişir)</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Genin yapısı değil, çalışma biçimi değişir.</text>\n  <text x="380" y="132" font-size="11.5" fill="#334155">• Sıcaklık, ışık, besin, nem, toprak pH\'ı etkiler.</text>\n  <text x="380" y="156" font-size="11.5" font-weight="bold" fill="#1e40af">• Hiçbir durumda KALITSAL DEĞİLDİR</text>\n  <text x="390" y="174" font-size="11" fill="#475569">(yavru döllere aktarılmaz).</text>\n  <text x="380" y="198" font-size="11.5" fill="#334155">• Etken ortadan kalkınca eski haline döner.</text>\n  <text x="380" y="220" font-size="11" font-weight="bold" fill="#1d4ed8">Örnek: Çuha çiçeği, Himalaya tavşanı, Bronzlaşma</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KLASİK MODİFİKASYON DENEYLERİ (GEN İŞLEYİŞİ DEĞİŞİMİ)</text>\n  <rect x="30" y="55" width="200" height="185" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="130" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Çuha Çiçeği (Sıcaklık)</text>\n  <text x="130" y="112" text-anchor="middle" font-size="11.5" fill="#334155">• 15 - 20 °C sıcaklıkta:</text>\n  <text x="130" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">KIRMIZI ÇİÇEK açar</text>\n  <text x="130" y="160" text-anchor="middle" font-size="11.5" fill="#334155">• 30 - 35 °C sıcaklıkta:</text>\n  <text x="130" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#475569">BEYAZ ÇİÇEK açar</text>\n  <text x="130" y="212" text-anchor="middle" font-size="11" fill="#9d174d">Genotip aynı, fenotip farklı!</text>\n  <rect x="250" y="55" width="200" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Himalaya Tavşanı (Sıcaklık)</text>\n  <text x="350" y="110" text-anchor="middle" font-size="11.5" fill="#334155">• Sırtındaki beyaz tüyler</text>\n  <text x="350" y="130" text-anchor="middle" font-size="11.5" fill="#334155">kazınıp BUZ bağlanırsa:</text>\n  <text x="350" y="155" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e293b">SİYAH kıl çıkar.</text>\n  <text x="350" y="185" text-anchor="middle" font-size="11" fill="#475569">• Kulak, burun ve ayakları</text>\n  <text x="350" y="205" text-anchor="middle" font-size="11" fill="#475569">soğuk olduğu için siyahtır.</text>\n  <rect x="470" y="55" width="200" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Bal Arıları (Beslenme)</text>\n  <text x="570" y="112" text-anchor="middle" font-size="11.5" fill="#334155">• Arı sütü ile beslenen larva:</text>\n  <text x="570" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">KRALİÇE ARI (Verimli)</text>\n  <text x="570" y="160" text-anchor="middle" font-size="11.5" fill="#334155">• Polen (çiçek tozu) ile:</text>\n  <text x="570" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">İŞÇİ ARI (Kısır)</text>\n  <text x="570" y="212" text-anchor="middle" font-size="11" fill="#854d0e">Besin genin işleyişini belirler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ADAPTASYON (ÇEVREYE UYUM): KALITSAL YAŞAMA ŞANSI</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kutup Ekosistemi Adaptasyonları</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Kutup Ayısı ve Kutup Tilkisi:</text>\n  <text x="65" y="130" font-size="11.5" fill="#334155">- Beyaz post rengi (Karda kamuflaj sağlar)</text>\n  <text x="65" y="152" font-size="11.5" fill="#334155">- Küçük kulak ve kısa burun (Isı kaybını azaltır)</text>\n  <text x="65" y="174" font-size="11.5" fill="#334155">- Deri altında kalın yağ tabakası (Soğuktan korur)</text>\n  <text x="65" y="196" font-size="11.5" fill="#334155">- Geniş ayak tabanları (Karda batmayı önler)</text>\n  <text x="187" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Aynı ortamda farklı türler benzer uyum gösterir!</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Çöl ve Su Ekosistemi Adaptasyonları</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Çöl Tilkisi ve Çöl Faresi:</text>\n  <text x="390" y="128" font-size="11" fill="#475569">Geniş kulak ve uzun kuyruk (Isı atımını artırır), kum rengi</text>\n  <text x="380" y="152" font-size="11.5" fill="#334155">• Kaktüs (Çöl): İğne yaprak (Su kaybını azaltır)</text>\n  <text x="380" y="174" font-size="11.5" fill="#334155">• Nilüfer (Su): Geniş yaprak (Terlemeyi artırır)</text>\n  <text x="380" y="198" font-size="11.5" font-weight="bold" fill="#15803d">• Tüm adaptasyonlar KALITSALDIR ve</text>\n  <text x="390" y="218" font-size="11" fill="#166534">nesilden nesile aktarılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
